<script lang="ts">
  import {t,canonicalT,locale} from '../../lib/i18n';
  import {onDestroy} from 'svelte';
  import {createMarketDataClient,type DatasetInfo,type ImportJob,type ArchiveType,type ArchivePeriod} from '../../lib/flow/persistence-client';
  let {symbol,active=true,onSelect}:{symbol:string;active?:boolean;onSelect:(dataset:DatasetInfo)=>void}=$props();
  const client=createMarketDataClient();
  let datasets=$state<DatasetInfo[]>([]),message=$state(''),busy=$state(false),job=$state<ImportJob>(),jobs=$state<ImportJob[]>([]);
  let period=$state<ArchivePeriod>('daily'),tradeType=$state<ArchiveType>('aggTrades'),from=$state(new Date(Date.now()-86400000).toISOString().slice(0,10)),to=$state('');
  let uploadFile=$state<File>(),checksum=$state(''),uploadDate=$state(new Date(Date.now()-86400000).toISOString().slice(0,10)),uploadAbort=$state<AbortController>();
  let generation=0;
  async function refresh(){const token=++generation;try{const [rows,tasks]=await Promise.all([client.datasets(symbol),client.jobs({limit:30})]);if(token===generation){datasets=rows;jobs=tasks.filter(task=>task.request.symbol===symbol);}}catch(error){if(token===generation)message=String(error);}}
  $effect(()=>{if(!active)return;symbol;void refresh();const timer=setInterval(()=>{void refresh();if(job&&['queued','running'].includes(job.status))void client.job(job.id).then(value=>job=value).catch(error=>message=String(error));},3000);return ()=>{clearInterval(timer);generation++;};});
  onDestroy(()=>uploadAbort?.abort());
  async function record(){busy=true;message='';try{const row=await client.startRecording(symbol);message=`后台录制已启动：${row.symbol}。关闭侧栏仍会继续；停止服务会安全落盘。`;await refresh();}catch(error){message=String(error);}finally{busy=false;}}
  async function stop(id:string){busy=true;try{await client.stopRecording(id);await refresh();message='录制已停止并保存。';}catch(error){message=String(error);}finally{busy=false;}}
  async function resume(id:string){busy=true;message='';try{const row=await client.resumeRecording(id);await refresh();message=`已人工恢复 ${row.symbol} 的原数据集。旧成交保留；暂停区间的历史L2保持缺口，新快照接续后继续。`;}catch(error){message=String(error);}finally{busy=false;}}
  async function importArchive(){busy=true;message='';try{job=await client.importArchives({symbol,type:tradeType,period,from,to:to||undefined});message='已进入后台导入队列，按官方校验和验证后入库。';}catch(error){message=String(error);}finally{busy=false;}}
  async function cancel(id:string){try{job=await client.cancelJob(id);await refresh();}catch(error){message=String(error);}}
  async function upload(){if(!uploadFile)return;busy=true;message='';uploadAbort=new AbortController();try{const row=await client.uploadArchive(uploadFile,{symbol,type:tradeType,period,date:uploadDate,checksum:checksum.trim().split(/\s+/)[0]},uploadAbort.signal);await refresh();onSelect(row);message='文件校验并导入完成。';}catch(error){message=String(error);}finally{busy=false;uploadAbort=undefined;}}
  const date=(time?:number)=>time?new Date(time).toLocaleString($locale,{hour12:false,timeZone:'UTC'}):'—';
  const stateLabel:Record<string,string>={queued:'队列中',running:'进行中',importing:'导入中',recording:'后台录制中',complete:'已完成',stopped:'已停止',failed:'失败',cancelled:'已取消'};
</script>
<section class="data-manager" aria-label={$t("本地行情数据管理")}>
  <header><h3>{$t("历史数据与后台录制")}</h3><button onclick={refresh}>{$t("刷新")}</button></header>
  <p>{$t("公开行情保存在本机磁盘；录制独立于侧栏。历史成交不等于历史盘口，深度只从真实录制的快照与增量恢复。")}</p>
  {#if message}<p class="notice" role="status">{$canonicalT(message)}</p>{/if}
  <div class="buttons"><button onclick={record} disabled={busy||datasets.some(d=>d.state==='recording')}>{$t("开始录制实时")} {symbol}</button></div>
  <details><summary>{$t("导入 Binance 官方档案")}</summary>
    <div class="fields"><label>{$t("数据类型")}<select bind:value={tradeType}><option value="aggTrades">{$t("聚合成交 aggTrades")}</option><option value="trades">{$t("原始成交 trades")}</option></select></label><label>{$t("档案粒度")}<select bind:value={period} onchange={event=>{period=event.currentTarget.value as ArchivePeriod;from=period==='daily'?new Date(Date.now()-86400000).toISOString().slice(0,10):new Date(Date.now()-32*86400000).toISOString().slice(0,7);to='';}}><option value="daily">{$t("日档案")}</option><option value="monthly">{$t("月档案")}</option></select></label></div>
    <div class="fields">{#if period==='daily'}<label>{$t("开始日期 UTC")}<input type="date" bind:value={from}/></label><label>{$t("结束日期（可选）")}<input type="date" bind:value={to}/></label>{:else}<label>{$t("开始月份 UTC")}<input type="month" bind:value={from}/></label><label>{$t("结束月份（可选）")}<input type="month" bind:value={to}/></label>{/if}</div>
    <button onclick={importArchive} disabled={busy||!from}>{$t("开始校验并导入")}</button><p>{$t("按所选日期逐个流式解压入库，支持取消；未完成文件不会标成完整数据。")}</p>
  </details>
  {#if job}<article><strong>{$t("导入任务 ·")} {$canonicalT(stateLabel[job.status]??job.status)}</strong><p>{$canonicalT(job.message)}</p><p>{job.completedFiles}/{job.files} {$t("文件 ·")} {job.rows.toLocaleString($locale)} {$t("行 ·")} {(job.bytes/1024/1024).toFixed(1)} MB</p>{#if ['queued','running'].includes(job.status)}<button onclick={()=>cancel(job!.id)}>{$t("取消导入")}</button>{/if}</article>{/if}
  {#each jobs.filter(task=>task.id!==job?.id&&['queued','running','failed'].includes(task.status)) as task}<article><strong>{task.request.from} · {$canonicalT(stateLabel[task.status])}</strong><p>{$canonicalT(task.message)}</p>{#if ['queued','running'].includes(task.status)}<button onclick={()=>cancel(task.id)}>{$t("取消后台任务")}</button>{/if}</article>{/each}
  <details><summary>{$t("从本机导入已下载 ZIP")}</summary><p>{$t("选择档案文件及其官方 CHECKSUM。文件流直接发送至本机服务，不读入整份浏览器内存。")}</p>
    <label>{$t("ZIP 文件")}<input type="file" accept=".zip,application/zip" onchange={e=>uploadFile=e.currentTarget.files?.[0]}/></label><label>{$t("该文件日期 / 月份")}<input bind:value={uploadDate} placeholder={period==='daily'?'YYYY-MM-DD':'YYYY-MM'}/></label><label>{$t("SHA-256 校验和")}<input bind:value={checksum} placeholder={$t("64位十六进制，可粘贴CHECKSUM整行")}/></label>
    <div class="buttons"><button onclick={upload} disabled={busy||!uploadFile||!/^\s*[a-f\d]{64}(\s|$)/i.test(checksum)}>{$t("校验并导入本机文件")}</button>{#if uploadAbort}<button onclick={()=>uploadAbort?.abort()}>{$t("取消上传")}</button>{/if}</div>
  </details>
  <h4>{$t("已保存的数据集")}</h4>
  {#each datasets as dataset (dataset.id)}<article><div class="dataset-head"><strong>{dataset.symbol} · {dataset.kind==='recording'?$t("成交与深度录制"):dataset.tradeType}</strong><span>{$canonicalT(stateLabel[dataset.state])}</span></div><small>{date(dataset.fromTime)} — {date(dataset.throughTime)} UTC</small><p>{dataset.tradeCount.toLocaleString($locale)} {$t("成交 ·")} {dataset.depthCount.toLocaleString($locale)} {$t("深度事件 ·")} {dataset.gapCount} {$t("缺口记录")}</p>{#if dataset.recordingPauses?.length}<p>{$t("暂停区间")} {dataset.recordingPauses.length} {$t("段 · 旧簿不会跨暂停时间延伸")}</p>{/if}{#if dataset.warning}<p class="warning">{$canonicalT(dataset.warning)}</p>{/if}<div class="buttons"><button onclick={()=>onSelect(dataset)} disabled={!dataset.tradeCount&&!dataset.depthCount}>{$t("查看 / 回放")}</button>{#if dataset.state==='recording'}<button disabled={busy} onclick={()=>stop(dataset.id)}>{$t("停止录制")}</button>{:else if dataset.kind==='recording'&&dataset.state==='stopped'}<button disabled={busy||datasets.some(d=>d.id!==dataset.id&&d.symbol===dataset.symbol&&d.state==='recording')} onclick={()=>resume(dataset.id)} title={$t("明确恢复此数据集；暂停期间L2仍缺失，成交只做有限真实补取")}>{$t("恢复此数据集录制")}</button>{/if}</div></article>{:else}<p>{$t("尚无本机数据集。可导入官方档案，或开始录制当前公开行情。")}</p>{/each}
</section>
<style>.data-manager{height:100%;overflow:auto;padding:12px;color:var(--text);font-size:11px}header{display:flex;align-items:center;justify-content:space-between}h3{font-size:13px;font-weight:500;margin:0}h4{font-size:11px;font-weight:500;margin:16px 0 9px}p{font-size:10px;line-height:1.8;margin:7px 0;color:var(--text-dim)}small{font:10px var(--mono);display:block;line-height:1.7;margin-top:6px;color:var(--text-dim)}button{border:1px solid var(--line-strong);padding:5px 7px;font-size:10px;color:var(--accent-strong);border-radius:1px}button:hover{background:var(--bg-active)}button:disabled{opacity:.4;cursor:default}.buttons{display:flex;gap:7px;flex-wrap:wrap;margin:8px 0}.fields{display:grid;grid-template-columns:1fr 1fr;gap:10px}label{display:flex;flex-direction:column;gap:5px;font-size:10px;color:var(--text-dim);margin:9px 0}input,select{background:var(--bg-panel);color:var(--text);border:1px solid var(--line-strong);border-radius:1px;font:10px var(--mono);min-width:0;padding:5px}details{padding:10px 0;border-block:1px solid var(--line-strong);margin-top:12px}summary{cursor:pointer;color:var(--text);line-height:1.6}article{border-bottom:1px solid var(--line-strong);padding:11px 0}.dataset-head{display:flex;gap:10px;justify-content:space-between}.dataset-head strong{font-size:11px;font-weight:500}.dataset-head span{font-size:10px;color:var(--accent-strong);white-space:nowrap}.notice{padding:9px;background:var(--bg-active);color:var(--text)}.warning{color:var(--warn)}button:focus-visible,input:focus-visible,select:focus-visible{outline:1px solid var(--accent);outline-offset:1px}</style>
